      const ticker=host.setInterval(()=>{if(!disposed&&run===r&&!r.cancelled){const seconds=Math.floor((Date.now()-started)/1000);debug.status=r.operation+'中：已等待 '+seconds+' 秒 / 上限 '+limit+' 秒';showDebug();say(debug.status);}},1000);
