   const thm=currentTheme();
   await animate(p,[collapsed(p),{transform:'none',opacity:1}],thm==='p5'?240:thm==='r1999'?560:440,thm==='p5'?'cubic-bezier(.18,1.5,.3,1)':thm==='r1999'?'cubic-bezier(.25,.8,.25,1)':'cubic-bezier(.16,1,.3,1)');if(id!==serial||disposed)return;
   await animate(splash,[{opacity:1,transform:'scale(1)'},{opacity:1,transform:'scale(1)',offset:.25},{opacity:0,transform:'scale(1.06)'}],thm==='p5'?320:thm==='r1999'?760:620,thm==='r1999'?'cubic-bezier(.25,.8,.25,1)':'ease-out');if(id!==serial||disposed)return;splash.hidden=true;
